use jet_devserver::{ResidentDevSession, WebHost::WebHost};
use std::{io::{self, BufRead}, path::Path, process::Command, sync::Arc};

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let entry = &args[1];
    let root = Path::new(&args[2]);
    let compiler = &args[3];
    let listener = WebHost::bind_application_preview_listener(Some(43947)).unwrap();
    let session = Arc::new(ResidentDevSession::new(entry, 0, 43947));
    let host = WebHost::bind_static_with_policy(entry, root, true, listener, session, Default::default()).unwrap();
    host.start_canvas();
    host.mark_ready(0, false);
    println!("READY production WebHost on 43947; controlled visual states, not CLI compilation proof");
    for line in io::stdin().lock().lines() {
        match line.unwrap().trim() {
            "building" => host.mark_building(),
            "ready" => host.mark_ready(0, true),
            "error" => {
                let output = Command::new(compiler).args(["check", entry, "--color=never"]).output().unwrap();
                assert!(!output.status.success(), "error capture requires a real compiler rejection");
                let diagnostic = format!("{}{}", String::from_utf8_lossy(&output.stdout), String::from_utf8_lossy(&output.stderr));
                let start = diagnostic.find("[E").expect("compiler rejection must have a registered error code") + 1;
                let end = diagnostic[start..].find(']').unwrap() + start;
                let code = diagnostic[start..end].to_string();
                std::fs::write(root.join("compiler-rejection.txt"), &diagnostic).unwrap();
                host.mark_error(code, diagnostic, true);
            }
            "quit" => break,
            command => panic!("unknown capture command: {command}"),
        }
    }
}
